INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(117844, 'ruRU', '', 'Применение этой атаки также заставляет твоего питомца поражать нескольких врагов веерным ударом.', 24330),
(117845, 'ruRU', '', 'Залп позволяет выпустить веер снарядов, поражающих нескольких врагов рядом с твоей целью.', 24330),
(117846, 'ruRU', '', 'Иногда ты окажешься в численном меньшинстве. Когда это случится, ты сможешь обрушить разрушение на целую орду противников одновременно!', 24330),
(117847, 'ruRU', '', 'Твой питомец погиб! Когда это происходит, способность Исцеление питомца меняется на Оживление питомца, что вернёт твоего верного спутника к жизни.', 24330),
(117848, 'ruRU', '', 'Используй Исцеление питомца, чтобы вылечить своего питомца.', 24330),
(117849, 'ruRU', '', 'Исцеление питомца позволит тебе вылечить урон, полученный твоим питомцем.', 24330),
(117850, 'ruRU', '', 'Твой питомец был ранен! К счастью, ты можешь помочь своему верному спутнику.', 24330),
(117851, 'ruRU', '', 'Используй Приказ: убить несколько раз на тренировочном манекене.', 24330),
(117852, 'ruRU', '', 'Не волнуйся, твой питомец вынослив! Приказ: убить заставит твоего питомца нанести мощную атаку, а также это отличный способ начать бой.', 24330),
(117853, 'ruRU', '', 'Отправив питомца атаковать и отвлечь врага, ты получаешь больше времени, чтобы подготовить свои атаки на расстоянии.', 24330),
(117854, 'ruRU', '', 'Используй Вызов питомца, чтобы призвать своего питомца в бой.', 24330),
(117855, 'ruRU', '', 'Вместе со своим верным питомцем ты хозяин своего окружения. Вызов питомца призовёт твоего питомца к тебе.', 24330),
(117856, 'ruRU', '', 'Охотники — повелители зверей обладают глубокой связью со своими питомцами, призывая и укрепляя их в бою, одновременно поражая врагов атаками на расстоянии.', 24330),
(117857, 'ruRU', '', 'Используй Залп!', 24330),
(117858, 'ruRU', '', 'Твой питомец ранен! Используй Исцеление питомца!', 24330),
(117859, 'ruRU', '', 'Используй Приказ: убить!', 24330),
(117860, 'ruRU', '', 'Приказ: убить доступен! Используй его сейчас!', 24330),
(117861, 'ruRU', '', 'Используй Дикого зверя!', 24330),
(117862, 'ruRU', '', 'Дикий зверь доступен! Используй его сейчас!', 24330),
(117863, 'ruRU', '', 'Используй Укус кобры!', 24330),
(117864, 'ruRU', '', 'Призови своего питомца!', 24330),
(117865, 'ruRU', '', 'Используй Ярость дикого зверя!', 24330),
(117866, 'ruRU', '', 'Ярость дикого зверя доступна! Используй её сейчас!', 24330),
(117867, 'ruRU', '', 'Отлично сделано, $p! Теперь ты готов сражаться как охотник — повелитель зверей.', 24330),
(117868, 'ruRU', '', 'Докажи мне, что у тебя есть необходимое умение и хитрость, чтобы охотиться на любую дичь!', 24330),
(117869, 'ruRU', '', 'Пока действует этот эффект, использование Дикого зверя сократит время до того, как ты сможешь снова применить Ярость дикого зверя.', 24330),
(117870, 'ruRU', '', 'В бою Ярость дикого зверя вводит тебя и твоего питомца в исступление ярости, что увеличивает ваш урон на короткое время.', 24330),
(117871, 'ruRU', '', 'Используй Ярость дикого зверя, атакуя тренировочный манекен.', 24330),
(117872, 'ruRU', '', 'Используй Укус кобры на тренировочном манекене.', 24330),
(117873, 'ruRU', '', 'Уверен, ты готов присоединиться к действию. Укус кобры — твоя основная атака на расстоянии, избивающая врага, пока твой питомец удерживает его внимание.', 24330),
(117874, 'ruRU', '', 'Используй Дикого зверя на тренировочном манекене.', 24330),
(117875, 'ruRU', '', 'Дикий зверь позволит тебе призвать находящегося рядом зверя, чтобы присоединиться к бою и атаковать твою цель на короткое время.', 24330),
(117876, 'ruRU', '', 'Теперь посмотрим, какими ещё силами природы ты повелеваешь.', 24330),
(117922, 'ruRU', '', 'Используй Снежную бурю, чтобы расправиться с этой группой врагов.', 24330),
(117923, 'ruRU', '', 'Ты можешь обстрелять указанную область осколками льда с помощью мощного заклинания под названием Снежная буря. Отличное название, не находишь?', 24330),
(117924, 'ruRU', '', 'Ты мастер нанесения урона множеству врагов одновременно.', 24330),
(117925, 'ruRU', '', 'Помни, что Клинок льда наносит дополнительный урон замороженным целям, так что использование Ледяной вспышки и Клинка льда вместе — мощная тактика.', 24330),
(117926, 'ruRU', '', 'Заморозь моего воина с помощью Ледяной вспышки.', 24330),
(117927, 'ruRU', '', 'Ледяная вспышка замораживает находящихся рядом врагов на месте, позволяя тебе отойти и безопасно уничтожить их. А пока просто потренируемся замораживать их на месте.', 24330),
(117928, 'ruRU', '', 'Что, если бы ты мог замораживать врагов на месте, не давая им даже добраться до тебя?', 24330);
